window.OLAYLAR_ORTACAG_CIN = [{"bolge":1,"t":"0577-01-17","kesinlik":"gun","b":"Kuzey Zhou ordusu Bingzhou'ya (Taiyuan/Jinyang) ulaştı; Kuzey Qi hükümdarı Ye'ye kaçtı","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Taiyuan","etiket":["savas","konu-siyasi"],"d":"Kuzey Zhou İmparatoru Wu'nun büyük ordusu Bingzhou'ya (Jinyang, bugünkü Taiyuan) geldi; Kuzey Qi hükümdarı kuzeni An De Prensi Yanzong'u Bingzhou'yu savunmaya bırakıp hafif süvarisiyle başkent Ye'ye kaçtı.","kaynak":"Linghu Defen vd., Zhou shu (çevrimiçi metin zh.wikisource.org/wiki/周書/卷06), juan 6 (Wu di xia): «建德五年…十二月…丁巳，大軍次幷州，齊主留其從兄安德王延宗守幷州，自將輕騎走鄴»"},{"bolge":1,"t":"0581-03-04","kesinlik":"gun","b":"Yang Jian Linguang Salonu'nda tahta çıktı: Sui hanedanı kuruldu","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["kurulus","konu-siyasi"],"d":"Kuzey Zhou imparatoru tahtı Yang Jian'a devretme fermanını yayımladıktan sonra Yang Jian, Zhou başkentinde saraya girip Linguang Salonu'nda imparator oldu; yıl adı Kaihuang'a çevrildi. Chang'an bölgesi Kuzey Zhou'dan Sui'ye geçti.","kaynak":"Wei Zheng vd., Sui shu (çevrimiçi metin zh.wikisource.org/wiki/隋書/卷01), juan 1 (Gaozu shang): «開皇元年二月甲子，上自相府常服入宮，備禮即皇帝位於臨光殿»"},{"bolge":1,"t":"0605-04-10","kesinlik":"gun","b":"Yangdi Luoyang'da Doğu Başkent'in (Dongjing) inşasını emretti","tur":"baskent","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Luoyang","etiket":["baskent","konu-siyasi"],"d":"Yang Guang, Yang Su, Yang Da ve Yuwen Kai'ya İ ve Luo nehirleri üzerinde Doğu Başkent'i kurmalarını, Yuzhou şehir halkını buraya yerleştirmelerini emretti; Luoyang ikinci bir başkent olarak kuruldu.","kaynak":"Wei Zheng vd., Sui shu (çevrimiçi metin zh.wikisource.org/wiki/隋書/卷03), juan 3 (Yangdi shang): «三月丁未，詔尚書令楊素、納言楊達、將作大匠宇文愷營建東京，徙豫州郭下居人以實之»"},{"bolge":1,"t":"0605-04-14","kesinlik":"gun","b":"Tongji Kanalı'nın açılmasına başlandı (Büyük Kanal'ın ilk kolu)","tur":"siyaset","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Luoyang","etiket":["siyaset","konu-siyasi"],"d":"Honan komutanlıklarından bir milyondan fazla erkek ve kadın toplandı; Batı Bahçe'den Gu ve Luo sularını Sarı Irmak'a, Banzhu'dan Sarı Irmak'ı Huai'ye bağlayan Tongji Kanalı kazıldı.","kaynak":"Wei Zheng vd., Sui shu (çevrimiçi metin zh.wikisource.org/wiki/隋書/卷03), juan 3 (Yangdi shang): «辛亥，發河南諸郡男女百餘萬，開通濟渠，自西苑引穀、洛水達于河，自板渚引河通于淮»"},{"bolge":1,"t":"0617-06-23","kesinlik":"gun","b":"Li Yuan Taiyuan'da Sui'ye karşı ayaklandı","tur":"isyan","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Taiyuan","etiket":["isyan","konu-siyasi"],"d":"Taiyuan muhafızı Tang Dükü Li Yuan, Sui'nin iki yetkilisini (Jiu Tang metninde Wei ve Junya) ihanetle suçlayıp idam ettirerek 'adalet ordusu' kaldırdı; Tang'ın kuruluşuna giden ayaklanma başladı.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷1), juan 1 (Gaozu): «五月甲子，高祖與威、君雅視事…即斬之以徇，遂起義兵» ; Wei Zheng vd., Sui shu (çevrimiçi metin zh.wikisource.org/wiki/隋書/卷04), juan 4 (Yangdi xia): «甲子，唐公起義師於太原»"},{"bolge":1,"t":"0617-12-12","kesinlik":"gun","b":"Li Yuan'ın orduları Sui başkenti Daxing'i (Chang'an) aldı","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["savas","konu-siyasi"],"d":"Li Yuan'ın ordusu Changle Sarayı'nda 200 bin kişiye ulaştıktan sonra şehre karşı koyan Sui bekçilerini yendi; Daxing alındı, karşı koyan komutanlar idam edildi ve birkaç gün sonra Yang You (Gongdi) Sui imparatoru ilan edilip Yangdi 'Emekli İmparator' sayıldı.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷1), juan 1 (Gaozu): «十一月丙辰，攻拔京城… 癸亥，率百僚…立代王侑為天子，遙尊煬帝為太上皇»"},{"bolge":1,"t":"0618-04-11","kesinlik":"gun","b":"Yangdi Jiangdu'da (Yangzhou) öldürüldü; Sui fiilen çöktü","tur":"hukumdar","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Yangzhou","yer":"Jiangdu (Yangzhou)","etiket":["hukumdar","konu-siyasi"],"d":"Yuwen Huaji, Jiangdu Sarayı'nda Sui Emekli İmparatoru Yangdi'yi öldürttü ve Yang Hao'yu kukla imparator yapıp kendini başbakan ilan etti; Tang hanedanı birkaç ay sonra kuruldu.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷1), juan 1 (Gaozu): «三月丙辰，右屯衛將軍宇文化及弒隋太上皇於江都宮，立秦王浩為帝» ; Wei Zheng vd., Sui shu (çevrimiçi metin zh.wikisource.org/wiki/隋書/卷04), juan 4 (Yangdi xia): «上崩于溫室，時年五十»"},{"bolge":1,"t":"0626-07-02","kesinlik":"gun","b":"Xuanwu Kapısı olayı: Li Shimin veliaht Jiancheng ve Yuanji'yi öldürdü","tur":"hukumdar","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["hukumdar","konu-siyasi"],"d":"Tang kurucusu Gaozu'nun oğlu Li Shimin (sonra Taizong), Chang'an sarayının Xuanwu Kapısı'nda pusu kurup kardeşleri veliaht Jiancheng ile Yuanji'yi öldürdü; birkaç gün içinde veliaht ilan edildi.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷2), juan 2 (Taizong shang): «六月四日，太宗率長孫無忌、尉遲敬德…於玄武門誅之» ; Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷191), Tang ji 7: «庚申，世民帥長孫無忌等入，伏兵於玄武門… 世民射建成，殺之»"},{"bolge":1,"t":"0626-09-03","kesinlik":"gun","b":"Taizong tahta çıktı (Li Shimin, Tang'ın ikinci imparatoru)","tur":"hukumdar","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["hukumdar","konu-siyasi"],"d":"Gaozu tahtı veliaht Li Shimin'e devretti; Taizong Doğu Saray'ın Xiande Salonu'nda tahta çıktı ve genel af ilan edildi.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷2), juan 2 (Taizong shang): «八月癸亥，高祖傳位於皇太子，太宗即位於東宮顯德殿»"},{"bolge":1,"t":"0626-09-25","kesinlik":"gun","b":"Wei Nehri (Bianqiao) antlaşması: Taizong ve Jieli Kağan beyaz at kurban ederek ant içti","tur":"antlasma","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["antlasma","konu-siyasi"],"d":"Doğu Türk Kağanı Jieli ordusu Wei Nehri'nin kuzeyine kadar inince Taizong köprü başında kağanla konuştu, ardından Bianqiao köprüsünde beyaz at kurban edilerek antlaşma yapıldı; Türk ordusu çekildi.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷2), juan 2 (Taizong shang): «乙酉，又幸便橋，與頡利刑白馬設盟，突厥引退»"},{"bolge":1,"t":"0634-01-01","kesinlik":"yil","b":"Tibet ilk kez Tang'a elçi gönderdi (Songtsen Gampo, 634)","tur":"siyaset","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Lhasa","etiket":["siyaset","konu-siyasi"],"d":"Genç yaşta tahta çıkan Tibet hükümdarı Songtsen Gampo (Qizong Nongzan), Zhenguan'ın 8. yılında Tang sarayına ilk elçiliği gönderdi; Tang kaynağı Tibet'in başkentini Luoxie şehri olarak anar (Lhasa).","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷196上), juan 196 shang (Tubo zhuan shang): «其國都城號為邏些城…貞觀八年，其贊普棄宗弄贊始遣使朝貢。弄贊弱冠嗣位»"},{"bolge":1,"t":"0640-10-11","kesinlik":"gun","b":"Xizhou'da An-Xi Genel Valiliği (Protectorate) kuruldu","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Gaochang","etiket":["siyaset","konu-siyasi"],"d":"Gaochang'ın ilhakından sonra yeni Xizhou eyaletinde ağır suçlar affedildi (9. ay癸卯) ve Xizhou'da An-Xi Genel Valiliği (Anxi duhufu) kuruldu.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷3), juan 3 (Taizong xia): «九月癸卯，曲赦西州大闢罪。乙卯，於西州置安西都護府»"},{"bolge":1,"t":"0641-01-01","kesinlik":"yil","b":"Prenses Wencheng Songtsen Gampo ile evlendirildi (641)","tur":"ittifak","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Lhasa","etiket":["ittifak","konu-siyasi"],"d":"Songtsen Gampo Songzhou'ya saldırıp Tang'dan yeniden evlilik talep ettikten sonra Taizong prensesi Wencheng'i ona verdi; Li Daozong gelini götürürken Songtsen ordusuyla Baihai'ye gelip onu Nehir Kaynağı'nda karşıladı, ülkesine dönünce prenses için bir şehir kurdurdu, halka yüz boyamayı bıraktırdı ve soylu çocukları Tang okuluna göndermek istedi.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷196上), juan 196 shang (Tubo zhuan shang): «貞觀十五年，太宗以文成公主妻之，令禮部尚書、江夏郡王道宗主婚，持節送公主於吐蕃。弄贊率其部兵次柏海，親迎於河源…當為公主築一城»"},{"bolge":1,"t":"0739-01-01","kesinlik":"yil","b":"Nanzhao başkentini Taihe Şehri'ne taşıdı (739)","tur":"baskent","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Dali","etiket":["baskent","konu-siyasi"],"d":"Tang'ın Yunnan Prensi unvanını verdiği Piluoge (Guiyi), Kaiyuan 27. yılında yerleşim merkezini Taihe (Dahe) Şehri'ne taşıdı; Taihe Erhai kıyısında, Dali yakınındadır.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷197), juan 197 (Nan Man Xi Nan Man zhuan): «二十六年，詔授特進，封越國公，賜名曰歸義。其後破洱河蠻，以功策授雲南王…二十七年，徙居大和城»"},{"bolge":1,"t":"0748-01-01","kesinlik":"yil","b":"Piluoge öldü; oğlu Geluofeng Yunnan Prensi olarak başa geçti (748)","tur":"hukumdar","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Dali","etiket":["hukumdar","konu-siyasi"],"d":"Nanzhao kurucusu Piluoge (Guiyi) Tianbao'nun 7. yılında öldü; Tang sarayı oğlu Geluofeng'i Yunnan Prensi unvanıyla ardıl yaptı. Metne göre Piluoge'nin ölümünden sonra Sichuan askerî valisi Xianyu Zhongtong ve Yunnan valisi Zhang Qiantuo Nanzhao'ya saygısız davrandı.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷197), juan 197 (Nan Man Xi Nan Man zhuan): «七年，歸義卒，詔立子閣羅鳳襲雲南王。無何，鮮于仲通為劍南節度使，張虔陀為雲南太守。仲通褊急寡謀，虔陀矯詐，待之不以禮»"},{"bolge":1,"t":"0751-01-01","kesinlik":"yil","b":"Nanzhao, Xi'er Nehri'nde Tang ordusunu bozdu ve Tibet'e bağlandı","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Dali","etiket":["savas","konu-siyasi"],"d":"Sichuan askerî valisi Xianyu Zhongtong'un yaklaşık 80 bin kişilik ordusu Lunan'da ve Xi'er Nehri (Erhai) kıyısında Nanzhao kralı Geluofeng'e yenildi (Zizhi tongjian: 60 bin ölü); Geluofeng ölüleri toplayıp zafer anıtı yaptırdı ve Tibet'e bağlandı.","kaynak":"Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷216), Tang ji 32: «夏，四月，壬午，劍南節度使鮮于仲通討南詔蠻，大敗於瀘南… 進軍至西洱河，與閣羅鳳戰，軍大敗，士卒死者六萬人… 遂北臣於吐蕃»"},{"bolge":1,"t":"0755-12-16","kesinlik":"gun","b":"An Lushan Fanyang'da (Youzhou) isyan bayrağını çekti","tur":"isyan","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Pekin (Hanbalık)","etiket":["isyan","konu-siyasi"],"d":"Fanyang (Youzhou) askerî valisi An Lushan, yaklaşık 150 bin kişilik Tong-luo, Xi, Khitan ve Shiwei destekli orduyla, 'Yang Guozhong'u cezalandırmak' bahanesiyle Chang'an'a yürüdü; yedi yıldan uzun sürecek An-Shi isyanı başladı.","kaynak":"Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷217), Tang ji 33: «十一月，甲子，祿山發所部兵及同羅、奚、契丹、室韋凡十五萬眾，號二十萬，反於范陽» ; Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷9), juan 9 (Xuanzong xia): «丙寅，范陽節度使安祿山率蕃、漢之兵十餘萬，自幽州南向詣闕，以誅楊國忠為名»"},{"bolge":1,"t":"0756-02-05","kesinlik":"gun","b":"An Lushan Luoyang'da 'Büyük Yan' imparatoru ilan etti","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Luoyang","etiket":["kurulus","konu-siyasi"],"d":"Luoyang'ı (Doğu Başkent) Ocak 756'da alan An Lushan, yeni yılın ilk gününde kendini Büyük Yan (Da Yan) imparatoru ilan etti, yıl adını Shengwu yaptı ve Yan saray teşkilatını kurdu.","kaynak":"Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷217), Tang ji 33: «至德元年…春，正月，乙卯朔，祿山自稱大燕皇帝，改元聖武» ; Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷9), juan 9 (Xuanzong xia): «十五載春正月乙卯，御宣政殿受朝。其日，祿山僭號於東京»"},{"bolge":1,"t":"0756-07-10","kesinlik":"gun","b":"Tongguan düştü: Ge Shuhan esir alındı, Chang'an yolu açıldı","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Tongguan","etiket":["savas","konu-siyasi"],"d":"Lingbao'da Cui Qianyou'ya yenilen (6. ay 8. gün) Tang ordusunun komutanı Ge Shuhan Tongguan'a çekilmiş, ertesi gün kendi subayı Huoba Guiren tarafından esir edilip isyancılara teslim edildi; geçit savunmasız kaldı, başkent paniğe düştü.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷9), juan 9 (Xuanzong xia): «庚寅，哥舒翰將兵八萬與賊將崔乾祐戰於靈寶西原，官軍大敗… 辛卯，哥舒翰至潼關，為其帳下火拔歸仁…執之降賊，關門不守，京師大駭»"},{"bolge":1,"t":"0756-07-14","kesinlik":"gun","b":"Xuanzong Chang'an'dan Shu'ya (Sichuan) kaçtı","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["siyaset","konu-siyasi"],"d":"Tongguan düştükten üç gün sonra (甲午) Xuanzong 'bizzat sefere çıkıyorum' fermanı verdi; ertesi gün (乙未) sabaha karşı Yanqiu Kapısı'ndan çıktı. Hafif yağmur yağıyordu; yanında yalnızca vezirler Yang Guozhong ve Wei Jiansu, hadım Gao Lishi, veliaht ve bir kısım prensler vardı, geri kalanlar yetişemedi.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷9), juan 9 (Xuanzong xia): «乙未，凌晨自延秋門出，微雨沾濕，扈從惟宰相楊國忠、韋見素、內侍高力士及太子…»"},{"bolge":1,"t":"0757-11-14","kesinlik":"gun","b":"Xiangji Tapınağı muharebesi: Tang-Uygur ordusu Chang'an'ı geri aldı","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["savas","konu-siyasi"],"d":"Ordu başkomutanı Guangping Prensi (Li Chu) komutasındaki yaklaşık 200 bin kişilik Tang-Uygur-Arap karışık ordu Xiangji Tapınağı'nın kuzeybatısında isyancı generalleri yendi (Jiu Tang: altmış bin baş), ertesi gün Batı Başkent Chang'an geri alındı.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷10), juan 10 (Suzong): «壬寅，與賊將安守忠、李歸仁等戰於香積寺西北，賊軍大敗，斬首六萬級，賊帥張通儒棄京城東走。癸卯，廣平王收西京»"},{"bolge":1,"t":"0763-02-17","kesinlik":"gun","b":"Shi Chaoyi'nin kesik başı Chang'an'a ulaştı: An-Shi isyanı bitti","tur":"isyan","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["isyan","konu-siyasi"],"d":"Shi Chaoyi, Youzhou valisi Li Huaixian'ın ordusunun peşine düşmesiyle Wenquan Kalesi yakınında ormanda kendini astı; Li Huaixian başını Tang'a gönderdi ve isyan yedi yılı aşkın bir sürenin ardından sona erdi.","kaynak":"Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷222), Tang ji 38: «朝義窮蹙，縊於林中，懷仙取其首以獻… 甲辰，朝義首至京師» ; Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷11), juan 11 (Daizong): «賊范陽尹李懷仙斬史朝義首來獻，請降»"},{"bolge":1,"t":"0763-11-18","kesinlik":"gun","b":"Tibet orduları Chang'an'a girdi; kukla imparator Cheng Hong'u tahta oturttu","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["savas","konu-siyasi"],"d":"Tibet ordusu Jingzhou'yu ele geçirip başkent bölgesine indikten sonra imparator Daizong Shaanzhou'ya kaçtı; Tibetliler Chang'an'a girip Prens Cheng Hong'u imparator ilan etti, hazineyi yağmaladı. Guo Ziyi'nin Shangzhou'da toparladığı kuvvetler ve Chang'an gençlerinin Zhuque Caddesi'nde davul çalarak başlattığı karşı koyma Tibet ordusunu sarstı.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷11), juan 11 (Daizong): «戊寅，吐蕃入京師，立廣武王承宏為帝» ; Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷223), Tang ji 39: «戊寅，吐蕃入長安，高暉與吐蕃大將馬重英等立…廣武王承宏為帝，改元，置百官»"},{"bolge":1,"t":"0821-01-01","kesinlik":"yil","b":"Tang-Tibet antlaşması Chang'an'da yemin edildi (821)","tur":"antlasma","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["antlasma","konu-siyasi"],"d":"Tibet 9. ayda barış isteyince Tang sarayı antlaşmanın atalar tapınağında ilan edilmesini gereksiz bulup Liu Yuanding'i 'Batı Barbarlarla Ant Elçisi' atadı; 10. ayın 10. günü Chang'an'da Tibet elçileriyle yemin edildi, iki devlet bildirilen sınırları koruyup birbirini işgal etmeyecekti. Liu Yuanding sonra Tibet karargâhına gidip ertesi yıl 5. ayın 6. günü yemini orada tamamladı (rapor 6. ayda geldi).","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷196下), juan 196 xia (Tubo zhuan xia): «長慶元年…九月，吐蕃遣使請盟，上許之…乃命大理卿、兼御史大夫劉元鼎充西蕃盟會使…十月十日，與吐蕃使盟，宰臣及右僕射…皆預焉…蕃、漢兩邦，各守見管本界，彼此不得征，不得討，不得相為寇讎，不得侵謀境上… 二年…六月…劉元鼎自吐蕃使回，奏云：去四月二十四日到吐蕃牙帳，以五月六日會盟訖»"},{"bolge":1,"t":"0842-01-01","kesinlik":"yil","b":"Tibet hükümdarının ölümü Tang'a bildirildi (842)","tur":"hukumdar","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Lhasa","etiket":["hukumdar","konu-siyasi"],"d":"Tibet zanpusunun ölümü Huichang 2. yılında (842) gerçekleşti; 12. ayda Tibet elçileri Lun Zan ve arkadaşları ölümü Tang sarayına bildirdi, Tang Yapı İşleri Müsteşarı Li Jing'i (將作少監) taziyeye gönderdi. Jiu Tang shu ölümün sebebini (suikast) yazmaz.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷196下), juan 196 xia (Tubo zhuan xia): «會昌二年，贊普卒。十二月，遣論贊等來告哀，詔以將作少監李璟弔祭之»"},{"bolge":1,"t":"0879-01-01","kesinlik":"yil","b":"Huang Chao Guangzhou'yu aldı; Lingnan valisi Li Tiao esir düştü (879)","tur":"isyan","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Kanton (Guangzhou)","etiket":["isyan","konu-siyasi"],"d":"Tianping ve Guangzhou askerî valiliği taleplerini reddeden Tang hükümeti ona yalnızca bir muhafız komutanlığı berat belgesi gönderince öfkelenen Huang Chao hükümet yetkililerine küfredip Guangzhou'ya saldırdı ve aynı gün aldı, Lingnan Doğu Yolu askerî valisi Li Tiao'yu esir tuttu ve Lingnan eyalet-ilçelerini yağmaladı.","kaynak":"Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷253), Tang ji 69: «巢復上表求廣州節度使…朝廷不許…九月，黃巢得率府率告身，大怒，詬執政，急攻廣州，即日陷之，執節度使李迢，轉掠嶺南州縣»"},{"bolge":1,"t":"0880-12-22","kesinlik":"gun","b":"Huang Chao Luoyang'a girdi; Doğu Başkent'in muhafızı şehri teslim etti","tur":"isyan","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Luoyang","etiket":["isyan","konu-siyasi"],"d":"Huang Chao'nun ordusu Luoyang'a girdi; muhafız Liu Yunzhang memurlarla birlikte onu karşıladı. Huang Chao halka dokunmadı, 'ahali sakin kaldı'.","kaynak":"Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷254), Tang ji 70: «丁卯，黃巢陷東都，留守劉允章帥百官迎謁。巢入城，勞問而已，閭裡晏然»"},{"bolge":1,"t":"0881-01-08","kesinlik":"gun","b":"Xizong Chang'an'dan kaçtı; Huang Chao'nun öncüleri şehre girdi","tur":"isyan","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["isyan","konu-siyasi"],"d":"Xizong, hadım Tian Lingzi komutasındaki 500 kişilik Shence muhafızıyla Jinguang Kapısı'ndan kaçtı; ikindiye doğru öncü general Chai Cun Chang'an'a girdi, Zhang Zhifang Bashang'da isyancıları karşıladı.","kaynak":"Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷254), Tang ji 70: «田令孜帥神策兵五百奉帝自金光門出… 晡時，黃巢前鋒將柴存入長安，金吾大將軍張直方帥文武數十人迎巢於霸上»"},{"bolge":1,"t":"0881-01-16","kesinlik":"gun","b":"Huang Chao Hanyuan Sarayı'nda imparator oldu: Büyük Qi (Da Qi)","tur":"isyan","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["isyan","konu-siyasi"],"d":"Huang Chao, Tang hanedanı mensuplarını öldürttükten sonra saraya girdi, Hanyuan Salonu'nda imparatorluğunu ilan etti, devlet adını Büyük Qi, yıl adını Jintong yaptı ve genel af çıkardı.","kaynak":"Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷254), Tang ji 70: «辛卯，巢始入宮。壬辰，巢即皇帝位於含元殿… 國號大齊，改元金統»"},{"bolge":1,"t":"0883-05-18","kesinlik":"gun","b":"Li Keyong'un ordusu Chang'an'a girdi; Huang Chao şehri yakıp kaçtı","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["savas","konu-siyasi"],"d":"Weinan'da bir günde üç kez yenilen Huang Chao'nun Chang'an'daki kuvvetleri dağıldı; Li Keyong ve müttefik orduları Guangtai Kapısı'ndan şehre girdi, Huang Chao saraylara ateş verip kaçtı.","kaynak":"Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷255), Tang ji 71: «甲辰，克用等自光泰門入京師，黃巢力戰不勝，焚宮室遁去»"},{"bolge":1,"t":"0904-02-10","kesinlik":"gun","b":"Zhaozong Chang'an'dan ayrıldı; şehir yıktırılıp başkent Luoyang'a taşındı","tur":"baskent","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["baskent","konu-siyasi"],"d":"Zhu Quanzhong, Zhaozong'un Luoyang'a taşınmasını talep edip Chang'an halkını kayıtlara göre göç ettirdi, evlerin kerestesini Wei ve Sarı Irmak üzerinden Luoyang'a yüzdürerek yıktırdı; imparator yola çıktı.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷20上), juan 20 shang (Zhaozong): «天祐元年春正月丁酉朔…己酉，全忠率師屯河中，遣牙將寇彥卿奉表請車駕遷都洛陽。全忠令長安居人按籍遷居，徹屋木，自渭浮河而下…丁巳，車駕發京師»"},{"bolge":1,"t":"0904-09-22","kesinlik":"gun","b":"Zhaozong Luoyang'da öldürüldü","tur":"hukumdar","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Luoyang","etiket":["hukumdar","konu-siyasi"],"d":"Luoyang'a taşınan Zhaozong, Zhu Quanzhong'un buyruğuyla generaller Zhu Youqong, Shi Shucong ve Haberleşme Sorumlusu Jiang Xuanhui tarafından Jiaodian Salonu'nda gece öldürüldü.","kaynak":"Liu Xu vd., Jiu Tang shu (çevrimiçi metin zh.wikisource.org/wiki/舊唐書/卷20上), juan 20 shang (Zhaozong): «八月壬辰朔。壬寅夜，朱全忠令左龍武統軍朱友恭、右龍武統軍氏叔琮、樞密使蔣玄暉弒昭宗於椒殿»"},{"bolge":1,"t":"0907-01-01","kesinlik":"yil","b":"Sonraki Liang Qian Liu'yu 'Wuyue Kralı' yaptı","tur":"kurulus","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Hangzhou","etiket":["kurulus","konu-siyasi"],"d":"Zhu Wen'in tahta çıkış fermanının ardından Zhejiang askerî valisi Qian Liu 'Wuyue Kralı' unvanını aldı; aynı fermanda Henan valisi Zhang Quanyi 'Wei Kralı' yapıldı.","kaynak":"Xue Juzheng vd., Jiu Wudai shi (çevrimiçi metin zh.wikisource.org/wiki/舊五代史/卷3), juan 3 (Liang Taizu ji san): «進封河南尹兼河陽節度使張全義為魏王，兩浙節度使錢鏐進封吳越王»"},{"bolge":1,"t":"0907-06-01","kesinlik":"gun","b":"Zhu Wen Daliang'da (Kaifeng) imparator oldu: Sonraki Liang kuruldu","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Kaifeng","etiket":["kurulus","konu-siyasi"],"d":"Zhu Wen, Tang Aidi'nin devrinden sonra Bianzhou/Daliang'da (Kaifeng) 'Büyük Liang' (Sonraki Liang) imparatoru olarak tahta çıktı; ","kaynak":"Xue Juzheng vd., Jiu Wudai shi (çevrimiçi metin zh.wikisource.org/wiki/舊五代史/卷3), juan 3 (Liang Taizu san): «甲子，張文蔚、楊涉乘輅自上源驛至… 王被袞冕，即皇帝位»"},{"bolge":1,"t":"0907-06-01","kesinlik":"gun","b":"Tang hanedanı sona erdi: Aidi tahtı Zhu Wen'e devretti","tur":"son","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xi'an (Chang'an)","etiket":["son","konu-siyasi"],"d":"Tang Zhaoxuan (Ai) İmparatoru tahttan çekilme fermanını verdi; seremoni heyeti Daliang'a (Kaifeng) gelip mühürleri Zhu Wen'e sundu ve Zhu Wen imparator oldu. Tang, 289 yıllık ömrünü tamamladı; Çin Beş Hanedan dönemine girdi.","kaynak":"Xue Juzheng vd., Jiu Wudai shi (çevrimiçi metin zh.wikisource.org/wiki/舊五代史/卷3), juan 3 (Liang Taizu san): «…唐昭宣帝降御劄禪位於梁… 帥百官備法駕，詣大樑。甲子，張文蔚、楊涉乘輅自上源驛至… 王被袞冕，即皇帝位»"},{"bolge":1,"t":"0907-11-03","kesinlik":"gun","b":"Wang Jian Chengdu'da imparator oldu: Büyük Shu (Önceki Shu)","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Çengdu (Chengdu)","etiket":["kurulus","konu-siyasi"],"d":"Shu Prensi Wang Jian, Zhu Wen'in Tang'ı devirmesinden sonra Tang'ın yeniden dirilmesi için çağrı yapmasına karşın kimse karşılık vermeyince generallerle imparatorluk ilanını görüştü, halkla birlikte Tang için üç gün yas tuttu ve 9. ayda imparator olup devlet adını 'Büyük Shu' koydu.","kaynak":"Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷266), Hou Liang ji 1: «蜀王與弘農王移檄諸道，云欲與岐王、晉王會兵興復唐室，卒無應者。蜀王乃謀稱帝…九月…蜀王會將佐議稱帝…帥吏民哭三日；己亥，即皇帝位，國號大蜀»"},{"bolge":1,"t":"0909-05-11","kesinlik":"gun","b":"Sonraki Liang, Fujian askerî valisi Wang Shenzhi'ye 'Min Kralı' unvanını verdi","tur":"kurulus","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Fuzhou","etiket":["kurulus","konu-siyasi"],"d":"Sonraki Liang'ın bir fermanıyla Fujian askerî valisi Wang Shenzhi 'Min Kralı' oldu; aynı fermanda Yiding'in Wang Chuzhi 'Beiping Kralı', Guangzhou'nun Liu Yin 'Nanping Kralı' unvanını aldı.","kaynak":"Xue Juzheng vd., Jiu Wudai shi (çevrimiçi metin zh.wikisource.org/wiki/舊五代史/卷4), juan 4 (Liang Taizu ji si): «制：易定節度使王處直進封北平王，福建節度使王審知封閩王，廣州節度使劉隱封南平王»"},{"bolge":1,"t":"0926-05-15","kesinlik":"gun","b":"Li Cunxu Luoyang'da isyancı askerlerce öldürüldü","tur":"hukumdar","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Luoyang","etiket":["hukumdar","konu-siyasi"],"d":"Yedu (Weizhou) askerî isyanı sırasında başkent Luoyang'da muhafız komutanı Guo Congqian kıtasıyla Xingjiao Kapısı'na saldırdı; Li Cunxu savunurken ok yiyip öğle vakti Jiangxiao Salonu'nun dehlizinde öldü.","kaynak":"Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷275), Hou Tang ji 4: «天成元年…夏，四月，丁亥朔…從馬直指揮使郭從謙…攻興教門… 俄而帝為流矢所中…帝殂» ; Xue Juzheng vd., Jiu Wudai shi (çevrimiçi metin zh.wikisource.org/wiki/舊五代史/卷34), juan 34 (Tang Zhuangzong ji ba): «亭午，崩於絳霄殿之廡下，時年四十三»"},{"bolge":1,"t":"0936-11-28","kesinlik":"gun","b":"Shi Jingtang Taiyuan'da Khitan desteğiyle imparator ilan edildi: Sonraki Jin kuruldu","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Taiyuan","etiket":["kurulus","konu-siyasi"],"d":"Sonraki Tang'ın Taiyuan askerî valisi Shi Jingtang, Khitan hükümdarı Taizong'un yardımıyla Taiyuan'ın (Jinyang) güneyinde kurulan sunakta 'Büyük Jin' imparatoru olarak taç giydi; Khitan Taizong'un ferman metni ona 'oğlum Jin Prensi' diye seslenir.","kaynak":"Xue Juzheng vd., Jiu Wudai shi (çevrimiçi metin zh.wikisource.org/wiki/舊五代史/卷75), juan 75 (Jin Gaozu ji 1): «乃命築壇於晉陽城南，冊立為大晉皇帝…維天顯九年，歲次丙申，十一月丙戌朔，十二日丁酉，大契丹皇帝若曰…咨爾子晉王» ; Liao shi, Taizong ji (Jiu Wudai shi dipnotunda alıntı): «十一月丁酉，冊敬瑭為大晉皇帝»"},{"bolge":1,"t":"0937-01-11","kesinlik":"gun","b":"Li Congke ailesiyle birlikte Luoyang'da kendini yaktı: Sonraki Tang sona erdi","tur":"son","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Luoyang","etiket":["son","konu-siyasi"],"d":"Sonraki Jin imparatoru Shi Jingtang Heyang'a ulaşınca Sonraki Tang'ın son imparatoru Li Congke, annesi imparatoriçe Cao ve ailesiyle birlikte sabah saatlerinde Xuanwu Kulesi'nde kendini yaktı; Jin imparatoru Luoyang'a girip küllerin arasında onun kemiklerini buldu.","kaynak":"Xue Juzheng vd., Jiu Wudai shi (çevrimiçi metin zh.wikisource.org/wiki/舊五代史/卷48), juan 48 (Tang Modi ji xia): «庚辰，晉高祖至河陽。辛巳辰時，帝舉族與皇太后曹氏自燔於元武樓。晉高祖入洛，得帝燼骨於火中»"},{"bolge":1,"t":"0947-02-24","kesinlik":"gun","b":"Khitan Taizong Kaifeng'de taht töreni yaptı; ferman 'Büyük Liao' adıyla çıkarıldı","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Kaifeng","etiket":["siyaset","konu-siyasi"],"d":"Zhang Yanze'nin öncü kuvvetiyle Kaifeng'e girilmesinden sonra Khitan hükümdarı 2. ayın ilk günü ana sarayda tören yaptı: Çinli memurlar Çin giysisiyle, Khitanlar Khitan giysisiyle sıraya girdi, ferman 'Büyük Liao Huitong 10. yıl' ifadesiyle çıkarıldı ve genel af ilan edildi.","kaynak":"Sima Guang, Zizhi tongjian (çevrimiçi metin zh.wikisource.org/wiki/資治通鑑/卷286), Hou Han ji 1: «二月，丁巳朔，契丹主服通天冠、絳紗袍，登正殿…下制稱大遼會同十年，大赦»"},{"bolge":1,"t":"0959-07-27","kesinlik":"gun","b":"Zhou Shizong (Chai Rong) öldü; Liang Prensi tabutun önünde imparator ilan edildi","tur":"hukumdar","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Kaifeng","etiket":["hukumdar","konu-siyasi"],"d":"Sonraki Zhou imparatoru Shizong Wanshui Salonu'nda 39 yaşında öldü; ertesi gün son vasiyeti okundu ve Liang Prensi tabutun önünde imparator ilan edildi.","kaynak":"Xue Juzheng vd., Jiu Wudai shi (çevrimiçi metin zh.wikisource.org/wiki/舊五代史/卷119), juan 119 (Zhou Shizong ji 6): «癸巳，帝崩於萬歲殿，聖壽三十九。甲午，宣遺制，梁王於柩前即皇帝位»"},{"bolge":1,"t":"0979-08-01","kesinlik":"gun","b":"Gaoliang Nehri Muharebesi: Song İmparatoru Taizong Youzhou önünde Khitan'a yenildi","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Pekin (Hanbalık)","etiket":["savas","konu-siyasi"],"d":"Song Taizong, 6. ayda Youzhou'ya (Liao'nun Güney Başkenti, bugünkü Pekin) ulaştı, komutanlarını dört koldan kuşatmaya yerleştirdi; 7. ayda Khitan ile Gaoliang Nehri'nde yapılan büyük savaşta Song ordusu bozguna uğradı ve ertesi gün geri çekilmeye başladı.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷004), juan 4 (Taizong ji 1): «庚午，次幽州城南，駐蹕寶光寺…壬申，命節度使…四面分兵攻城…秋七月…癸未，帝督諸軍及契丹大戰于高梁河，敗績。甲申，班師»"},{"bolge":1,"t":"0994-03-01","kesinlik":"gun","b":"Li Shun'un isyancıları Chengdu'yu aldı (Wang Xiaobo-Li Shun ayaklanması)","tur":"isyan","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Çengdu (Chengdu)","etiket":["isyan","konu-siyasi"],"d":"Chunhua 4. yılın 12. ayında Wang Xiaobo'nun Jiangyuan'da öldürülmesinin ardından ayaklanmanın başına geçen Li Shun, bir sonraki yılın 1. ayında Hanzhou ve Pengzhou'yu aldı, ayın 16. günü (己巳) Chengdu'yu ele geçirdi; vali Guo Zai Zizhou'ya kaçtı, Li Shun şehre yerleşti ve isyancılar çevre eyaletlere saldırdı.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷005), juan 5 (Taizong ji 2): «十二月…戊申…小波中流矢死，眾推其黨李順為帥。淳化五年春正月甲寅朔…戊午，李順陷漢州，己未，陷彭州…己巳，李順陷成都，知府郭載奔梓州，順入據之»"},{"bolge":1,"t":"1038-01-01","kesinlik":"yil","b":"Li Yuanhao imparatorluğunu ilan etti (Batı Xia, Xingzhou)","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Yinchuan (Ningxia)","etiket":["kurulus","konu-siyasi"],"d":"Tangut hükümdarı Li Yuanhao Xia, Yin, Sui, You, Jing, Ling, Yan, Hui, Sheng, Gan, Liang, Gua, Sha ve Su eyaletlerini ele geçirdikten sonra Xingzhou'da (daha sonra Xingqing) kaldı, nehre ve Helan Dağı'na dayanan düzeni kurdu; Song'un Fuyan bölgesine saldırmak için boy beyleriyle kan yemini edip sunak yaptırarak imparator oldu (30 yaşında).","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷485), juan 485 (Xia guo zhuan shang): «元昊既悉有夏、銀、綏、宥、靜、靈、鹽、會、勝、甘、涼、瓜、沙、肅…仍居興州，阻河依賀蘭山為固…宋寶元元年…與諸豪歃血約先攻鄜延…遂築壇受冊，即皇帝位，時年三十»"},{"bolge":1,"t":"1040-01-01","kesinlik":"yil","b":"Xia ordusu Yanzhou'ya saldırdı; Fuyan ve Huanqing yollarının iki komutan yardımcısı yakalandı","tur":"savas","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Yan'an","etiket":["savas","konu-siyasi"],"d":"Kangding 1. yılının 1. ayında Zhao Yuanhao (Li Yuanhao) Yanzhou'ya (Yan'an) saldırdı ve Fuyan ile Huanqing yollarının başkomutan yardımcılarını ele geçirdi. Aynı yılın 3. ayında Song sarayı Shaanxi'nin saldırı-savunma planlarını tartıştı ve Han Qi'ye Shaanxi şehirlerinin onarımını verdi.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷010), juan 10 (Renzong ji 2): «康定元年春正月…是月，元昊寇延州，執鄜延、環慶兩路副都總管…三月丙辰，詔大臣條陝西攻守策…癸亥，命韓琦治陝西城池»"},{"bolge":1,"t":"1100-02-23","kesinlik":"gun","b":"Zhezong öldü; Prens Duan (Huizong) Kaifeng'de imparator oldu","tur":"hukumdar","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Kaifeng","etiket":["hukumdar","konu-siyasi"],"d":"Zhezong oğulsuz öldü; Dul İmparatoriçe perde arkasından naip oldu, Zhang Dun'un 'ayni anadan kardeş Prens Jian seçilmeli' görüşüne karşılık Prens Shen'in gözlerinin hasta olduğunu söyleyip Prens Duan'ın seçilmesini istedi; Prens Duan saraya çağrılıp imparator ilan edildi, ertesi gün genel af çıkarıldı.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷019), juan 19 (Huizong ji 1): «元符三年正月己卯，哲宗崩，皇太后垂簾…於是惇為之默然。乃召端王入，即皇帝位，皇太后權同處分軍國事。庚辰，赦天下»"},{"bolge":1,"t":"1126-01-19","kesinlik":"gun","b":"Huizong tahttan çekildi, Qinzong Kaifeng'de imparator oldu","tur":"hukumdar","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Kaifeng","etiket":["hukumdar","konu-siyasi"],"d":"Jin tehdidi altında Huizong, kendine 'Daojun Huangdi' unvanını alıp veliaht Zhao Huan'a (Qinzong) tahtı devretti; Qinzong gözyaşlarıyla reddedip hastalansa da ertesi gün Chuigong Salonu'nda memurlarını kabul ederek imparator oldu, Huizong Longde Sarayı'na çekildi.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷023), juan 23 (Qinzong ji): «宣和七年十二月…庚申，徽宗詔皇太子嗣位，自稱曰「道君皇帝」…辛酉，即皇帝位，御垂拱殿見群臣…引道君皇帝出居龍德宮»"},{"bolge":1,"t":"1126-03-04","kesinlik":"gun","b":"Jin ordusu Kaifeng önünden çekildi: ilk kuşatma sona erdi","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Kaifeng","etiket":["savas","konu-siyasi"],"d":"Jin elçilerinin altın-gümüş tazminat ve Taiyuan, Zhongshan, Hejian şehirlerinin devri talebine (1. ay) Song, 2. ayda 'üç şehrin devrini' kabul etti; Prens Kang Jin kampından döndü, Jin elçisi veda edip ordusunu çekti ve başkentte olağanüstü hal kaldırıldı.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷023), juan 23 (Qinzong ji): «二月丁酉朔…辛丑，又命資政殿大學士宇文虛中、知東上閣門事王球使之，許割三鎮地…乙巳，宇文虛中、王球復使金軍。康王至自金軍。金人遣韓光裔來告辭，遂退師，京師解嚴»"},{"bolge":1,"t":"1127-04-20","kesinlik":"gun","b":"Jin, Kaifeng'de Zhang Bangchang'ı 'Chu' imparatoru yaptı","tur":"siyaset","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Kaifeng","etiket":["siyaset","konu-siyasi"],"d":"Kaifeng'i aldıktan sonra Jin, imparator Qinzong'un Qingcheng'deki Jin kampında tutulduğu sırada, 3. ayın 7. günü Song vezirlerinden Zhang Bangchang'ı kukla 'Chu' imparatoru ilan etti.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷023), juan 23 (Qinzong ji): «靖康二年…三月辛卯朔，帝在青城。丁酉，金人立張邦昌為楚帝»"},{"bolge":1,"t":"1127-05-13","kesinlik":"gun","b":"Jin, Huizong ile Qinzong'u ve saray hazinesini Kuzey'e götürdü","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Kaifeng","etiket":["siyaset","konu-siyasi"],"d":"3. ayın sonunda (丁巳) Jin, Emekli İmparator Huizong'u kuzeye yürümeye zorladı; 4. ayın ilk günü imparator Qinzong, imparatoriçe ve veliaht da götürüldü; saray arabaları, tapınak eşyaları, harita ve kitaplar, zanaatkârlar ve hazine Kaifeng'den boşaltıldı.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷023), juan 23 (Qinzong ji): «丁巳，金人脅上皇北行。夏四月庚申朔，…金人以帝及皇后、皇太子北歸。凡法駕、鹵簿…太清樓秘閣三館書、天下州府圖及官吏、內人、內侍、技藝、工匠…府庫畜積，為之一空»"},{"bolge":1,"t":"1129-02-23","kesinlik":"gun","b":"Jin öncüleri Yangzhou'ya ulaştı: Gaozong Yangzhou'dan Zhenjiang'a kaçtı","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Yangzhou","etiket":["savas","konu-siyasi"],"d":"Jin süvarilerinin yaklaştığı haberi gelince İmparator Gaozong zırhını giyip aceleyle Zhenjiang'a kaçtı; Jin ordusu aynı gün Yangzi Köprüsü'nü geçti, ertesi gün öncüler Guazhou'ya ulaştı, Taimiao tabletleri taşınırken Taizu'nun tableti kaybedildi; ayın 戊辰 gününde Jin Yangzhou'yu yaktı.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷025), juan 25 (Gaozong ji 2): «二月庚戌朔…壬子，內侍鄺詢報金兵至，帝被甲馳幸鎮江府。是日，金兵過楊子橋。癸丑，遊騎至瓜洲… 戊辰，出米十萬斛…金人焚揚州»"},{"bolge":1,"t":"1129-03-05","kesinlik":"gun","b":"Gaozong Hangzhou'ya vardı ve konakladı (1129)","tur":"baskent","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Hangzhou","etiket":["baskent","konu-siyasi"],"d":"Yangzhou'dan Zhenjiang, Changzhou, Pingjiang ve Xiuzhou üzerinden kaçan Gaozong, ayın 壬戌 gününde Hangzhou'ya vardı ve burada konakladı; ertesi gün kendini suçlayan ferman çıkarıp doğrudan görüş istedi.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷025), juan 25 (Gaozong ji 2): «庚申，次崇德縣…壬戌，駐蹕杭州…癸亥，下詔罪己，求直言»"},{"bolge":1,"t":"1129-03-26","kesinlik":"gun","b":"Miao Fu ve Liu Zhengyan darbesi: Wang Yuan öldürüldü, Gaozong tahttan çekilmeye zorlandı","tur":"isyan","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Hangzhou","etiket":["isyan","konu-siyasi"],"d":"Muhafız komutanları Miao Fu ve Liu Zhengyan askerleriyle saraya yürüyüp Wang Yuan ile hadım Kang Lü ve yüzden fazla kişiyi öldürdü; Gaozong'u küçük oğlu lehine çekilmeye zorlayıp Dul İmparatoriçe Longyou'nun perde arkasından naiplik etmesini istediler. Gaozong ertesi gün 'Ruisheng Renxiao' unvanıyla emekliye ayrıldı; 6 gün sonra yıl adı Mingshou yapıldı.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷025), juan 25 (Gaozong ji 2): «癸未，傅、正彥等叛，勒兵向闕，殺王淵及內侍康履以下百餘人…傅等迫帝遜位於皇子魏國公，請隆祐太后垂簾同聽政…甲申，尊帝為睿聖仁孝皇帝…己丑，改元明受»"},{"bolge":1,"t":"1129-08-01","kesinlik":"gun","b":"Hangzhou 'Lin'an Prefecture'e (Lin'an fu) yükseltildi","tur":"siyaset","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Hangzhou","etiket":["siyaset","konu-siyasi"],"d":"Gaozong sarayı Hangzhou'yu Lin'an Valiliği (Lin'an fu) olarak yükseltti.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷025), juan 25 (Gaozong ji 2): «辛卯，升杭州為臨安府»"},{"bolge":1,"t":"1130-01-22","kesinlik":"gun","b":"Jin generali Wuzhu Lin'an'a saldırdı; vali şehri terk etti","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Hangzhou","etiket":["savas","konu-siyasi"],"d":"Kış ortasında Jin komutanı Wuzhu Lin'an Valiliği'ne (Hangzhou) saldırdı; vali Kang Yunzhi şehri bırakıp kaçtı, Qiantang ilçe yöneticisi Zhu Bi savunurken öldü. Gaozong büyük bir gemiyle Dinghai ilçesine çekildi.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷025), juan 25 (Gaozong ji 2): «十二月…乙酉，兀朮犯臨安府，守臣康允之棄城走，錢塘縣令朱蹕死之。己丑，帝乘樓船次定海縣»"},{"bolge":1,"t":"1141-12-17","kesinlik":"gun","b":"Song-Jin barış şartları belirlendi: sınır Huai Nehri, yıllık 250 bin tael gümüş ve 250 bin top ipek","tur":"antlasma","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Hangzhou","etiket":["antlasma","konu-siyasi"],"d":"Jin elçisi Xiao Yi ve arkadaşlarının Song sarayında kabul edilmesiyle barış yemini şartları belirlendi: sınır Huai Nehri'nin ortasından geçecek, Tang ve Deng eyaletleri Jin'e bırakılacak, Song her yıl 250 bin tael gümüş ve 250 bin top ipek ödeyecekti; aynı ay barış anlaşması tamamlanıp bildirgesi yazıldı.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷029), juan 29 (Gaozong ji 6): «壬子，蕭毅等入見，始定議和盟誓…是月，與金國和議成，立盟書，約以淮水中流畫疆，割唐、鄧二州界之，歲奉銀二十五萬兩、絹二十五萬匹»"},{"bolge":1,"t":"1142-01-27","kesinlik":"gun","b":"Yue Fei ve Zhang Xian Dali Mahkemesi'nde yargılandı; Yue Fei'ye ölüm verildi","tur":"siyaset","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Hangzhou","etiket":["siyaset","konu-siyasi"],"d":"10. ayın 戊寅 gününde Yue Fei ve Zhang Xian Dali Hapishanesi'ne atılıp sorguya çekildi; 12. ayın 癸巳 gününde Yue Fei'ye Dali Mahkemesi'nde ölüm hükmü verildi, oğlu Yue Yun ile Zhang Xian çarşıda idam edildi, aileleri Guangnan'a sürüldü.","kaynak":"Tuotuo vd., Song shi (çevrimiçi metin zh.wikisource.org/wiki/宋史/卷029), juan 29 (Gaozong ji 6): «戊寅，下岳飛、張憲大理獄… 十二月…癸巳，賜岳飛死于大理寺，斬其子雲及張憲于市，家屬徙廣南»"},{"bolge":1,"t":"1259-09-27","kesinlik":"gun","b":"Kubilay Yangtze'yi geçip Ezhou'yu (Wuchang) kuşattı (1259)","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Wuchang (Wuhan)","etiket":["savas","konu-siyasi"],"d":"Kubilay, Song seferinde 8. ayda Huai'yı geçip Huangpi'ye ulaştı; ardından ordusunu üç kolla Yangtze'den geçirip güney kıyısına çıkardı, 9. ayda Ezhou önüne gelip ertesi gün (庚戌) şehri kuşattı; Song generali Lü Wende Chongqing'den gelip geceleyin şehre girerek savunmayı sıkılaştırdı.","kaynak":"Song Lian vd., Yuan shi (çevrimiçi metin zh.wikisource.org/wiki/元史/卷004), juan 4 (Shizu ji 1): «歲己未…八月丙戌，渡淮…壬辰，次黃陂…三道並進…逕達南岸…九月…己酉，抵鄂，屯兵教場。庚戌，圍鄂…呂文德自重慶來…文德乘夜入鄂城，守愈堅»"},{"bolge":1,"t":"1270-08-18","kesinlik":"gun","b":"Yuan, Xiangyang'ı kuşatmak için çevre kalesi (huancheng) yaptı","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Xiangyang","etiket":["savas","konu-siyasi"],"d":"Yuan, Xiangyang'ı kuşatmak için çevresine kuşatma duvarı (huancheng) çekmeye başladı; 9. ayda Song generali Fan Wenhu'nun 2000 gemilik yardım filosuna karşı Yuan komutanları A'zhu, Hada ve Liu Zheng Guanzi Sığlığı'nda savaştı.","kaynak":"Song Lian vd., Yuan shi (çevrimiçi metin zh.wikisource.org/wiki/元史/卷007), juan 7 (Shizu ji 4): «八月戊辰朔，築環城以逼襄陽…九月…宋將范文虎以兵船二千艘來援襄陽，阿朮、合答、劉整率兵逆戰于灌子灘»"},{"bolge":1,"t":"1271-12-18","kesinlik":"gun","b":"Kubilay 'Yuan' (Büyük Yuan) hanedan adını ilan etti","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Pekin (Hanbalık)","etiket":["kurulus","konu-siyasi"],"d":"11. ayın 15. günü saray törenlerinde resmî kıyafet kararı alındı, Jin Taihe yasalarının uygulanması yasaklandı ve 'Büyük Yuan' devlet adı ilan edildi.","kaynak":"Song Lian vd., Yuan shi (çevrimiçi metin zh.wikisource.org/wiki/元史/卷007), juan 7 (Shizu ji 4): «十一月辛酉朔…乙亥，劉秉忠及王磐、徒單公履等言…具公服迎拜行禮。從之。禁行金泰和律。建國號曰大元，詔曰»"},{"bolge":1,"t":"1272-03-04","kesinlik":"gun","b":"Zhongdu'nun adı Dadu (Büyük Başkent) yapıldı","tur":"baskent","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Pekin (Hanbalık)","etiket":["baskent","konu-siyasi"],"d":"Yuan sarayı Zhongdu'nun adını Dadu olarak değiştirdi; aynı günlerde Koryo kralının elçisi Wang Shu (Qi'an Marki) yeni devlet adının ilanını kutlamaya geldi.","kaynak":"Song Lian vd., Yuan shi (çevrimiçi metin zh.wikisource.org/wiki/元史/卷007), juan 7 (Shizu ji 4): «壬辰，高麗國王王禃遣其臣齊安侯王淑來賀改國號。改中都為大都»"}];

;
/* ==== data/olaylar_ortacag_dogu_guneydogu_asya.js ==== */
// data/olaylar_ortacag_dogu_guneydogu_asya.js — paketle.py İNCELTTİ: ic_not* alanları yayına gitmez (kaynak dosya değişmedi)
window.OLAYLAR_ORTACAG_DOGU_GUNEYDOGU_ASYA = [{"bolge":1,"t":"0682-04-23","kesinlik":"gun","b":"Kedukan Bukit yazıtı: Sriwijaya kralı 23 Nisan 682'de sudan-karadan siddhayatra seferine çıktı; bir ay sonra zaferle Sriwijaya'ya döndü","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Palembang","etiket":["kurulus","konu-siyasi"],"d":"Palembang yakınında Seguntang tepesinin eteğindeki Kedukan Bukit yazıtına göre bir kral 23 Nisan 682'de tekneyle sefere çıktı, 19 Mayıs'ta bir ağızdan ordusuyla (kara ve deniz) ayrıldı ve bir ay sonra Sriwijaya'ya zafer, güç ve servet getirdi. Metin Sriwijaya'nın bilinen ilk tarihli belgesidir.","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, bölüm VI.1 («tells us that on April 23, 682, a king began an expedition (siddhayatra) by boat, that on May 19 he left an estuary ... and that, a month later, he brought victory, power, and wealth to Srivijaya»)"},{"bolge":1,"t":"0802-01-01","kesinlik":"yil","b":"II. Jayavarman Kulen tepesinde (Mahendraparvata) kraliyet lingasını diktirip Kmer krallığını Cava üstünlüğünden kurtardı; Angkor dönemi başladı","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Angkor (Siem Reap)","etiket":["kurulus","konu-siyasi"],"d":"Sdok Kak Thom steline göre Brahman Hiranyadama, Kambuja ülkesinin bir daha Cava'ya bağlı olmaması ve tek bir çakravartin hükümdar bulunması için devarâja ayinini yaptı. Coedès bu kutsamayı 802'ye tarihler; krallık Hariharalaya (Roluos), Amarendrapura ve Mahendraparvata (Phnom Kulen) arasında dolaşarak Angkor çevresinde birleşti.","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, s.98-100 ve s.249 (Sdok Kak Thom steli; «the establishment in 802 ... of the royal linga on the hill of Kulen»)"},{"bolge":1,"t":"0825-01-01","kesinlik":"yil","b":"Mon başkenti Hamsavati (Pegu), Thaton'lu ikiz kardeşler Samala ve Vimala tarafından kuruldu (kroniğe göre 825)","tur":"kurulus","onem":2,"dunya":1,"kapsam":"dis","yer_id":"Pegu (Bago)","etiket":["kurulus","konu-siyasi"],"d":"Coedès, Mon ülkesinin ağırlık merkezinin batıya kaydığını; bir kroniğin Pegu'nun (Hamsavati) kuruluş tarihi olarak 825'i verdiğini ve bu tarihin öbür metinlerin verdiği daha erken ya da geç tarihlere tercih edilebilir olduğunu yazar.","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, s.106-107 (bölüm VII.3; «a chronicle gives 825 as the date for the foundation of Pegu (Hamsavati) by Samala and Vimala»)"},{"bolge":1,"t":"0849-01-01","kesinlik":"yil","b":"Pagan (Arimaddanapura) şehri kuruldu: İrravadi-Chindwin birleşiminde, Pyu çöküşünden doğan yeni merkez","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Pagan","etiket":["kurulus","konu-siyasi"],"d":"Coedès'e göre Prome'nin nüfus kaybı Pagan'a yaradı; birkaç köyün birleşmesiyle oluşan Pagan (Arimaddanapura) İrravadi ile Chindwin'in kavşağında, Assam, Yunnan ve Shan yollarının kesiştiği yerde 849'da kuruldu.","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, bölüm VII.3 (s.105-107; başlık: «Foundation of Pegu (Hamsavati) in 825 and of Pagan (Arimaddanapura) in 849»)"},{"bolge":1,"t":"0918-07-25","kesinlik":"gun","b":"Wang Geon (Taejo) Gaegyeong'de Bojeong Salonu'nda tahta çıktı, ülkenin adını Goryeo koydu","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Kaesong","etiket":["kurulus","konu-siyasi"],"d":"Taebong'un generalleri Hong Yu, Bae Hyeongyeong, Sin Sung-gyeom ve Bok Ji-gyeom'un ayaklanmasıyla Gungye devrildi; Wang Geon 918 yazında tahta çıkıp ülkeyi Goryeo adıyla ilan etti ve Cheonsu ('Göğün Armağanı') saltanat adını verdi. Başkent Gaegyeong (Kaesong) oldu.","kaynak":"Goryeosa (高麗史, Koryŏ-sa; Wikisource neşri, zh.wikisource.org/wiki/高麗史), Sega 1 (卷一) Taejo 1. yıl: «元年夏六月丙辰，卽位于布政殿，國號高麗，改元天授»"},{"bolge":1,"t":"0929-01-01","kesinlik":"yil","b":"Orta Cava Medang krallığının idari merkezi Wawa döneminde (927-28) doğuya taşındı; Sindok 929'da tahta çıktı (Doğu Cava dönemi)","tur":"baskent","onem":2,"dunya":1,"kapsam":"dis","yer_id":"Malang","etiket":["baskent","konu-siyasi"],"d":"Coedès, yazıtların bulunduğu yerlere bakarak krallığın idari merkezinin Wawa'nın saltanatı (927-928) sırasında doğuya taşındığını; 919 yazıtında adı geçen Rakai Halu Sindok'un on yıl sonra, 929'da tahta çıktığını yazar. Böylece Medang'ın merkezi Brantas havzasına kaydı. (Brantas havzası Doğu Cava.)","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, bölüm VIII (Cava Mataram krallığı; «Wawa reigned in 927-28 ... the administrative center of the kingdom was moved to the east»)"},{"bolge":1,"t":"0929-01-01","kesinlik":"yil","b":"Orta Cava Medang krallığının idari merkezi Wawa döneminde (927-28) doğuya taşındı; Sindok 929'da tahta çıktı (Doğu Cava dönemi)","tur":"baskent","onem":2,"dunya":1,"kapsam":"dis","yer_id":"Surabaya","etiket":["baskent","konu-siyasi"],"d":"Coedès, yazıtların bulunduğu yerlere bakarak krallığın idari merkezinin Wawa'nın saltanatı (927-928) sırasında doğuya taşındığını; 919 yazıtında adı geçen Rakai Halu Sindok'un on yıl sonra, 929'da tahta çıktığını yazar. Böylece Medang'ın merkezi Brantas havzasına kaydı. (Brantas deltası Doğu Cava.)","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, bölüm VIII (Cava Mataram krallığı; «Wawa reigned in 927-28 ... the administrative center of the kingdom was moved to the east»)"},{"bolge":1,"t":"0935-12-10","kesinlik":"gun","b":"Silla kralı Gyeongsun maiyetiyle Gaegyeong'e girdi; Taejo onu törenle karşıladı ve kızı Nangnang Prenses'i evlendirdi","tur":"siyaset","onem":2,"dunya":1,"kapsam":"dis","yer_id":"Kaesong","etiket":["siyaset","konu-siyasi"],"d":"Silla kralı Kim Bu (Gyeongsun), 935'in 10. ayında Goryeo'ya başvurduktan sonra 11. ayda başkenti terk edip büyük bir maiyetle yola çıktı; yolun bütün ilçeleri onu ağırladı. Gaegyeong'e girişinde Taejo onu törenle karşıladı, Yuhwa Sarayı'nda konakladı.","kaynak":"Goryeosa (高麗史, Koryŏ-sa; Wikisource neşri, zh.wikisource.org/wiki/高麗史), Sega 2 (卷二) Taejo 18. yıl: «冬十一月…癸卯，羅王與王鐵等入開京，王備儀仗，出郊迎勞»"},{"bolge":1,"t":"0936-09-26","kesinlik":"gun","b":"Ilicheon'da Goryeo, Hubaekje ordusunu yendi; Sin-geom teslim oldu, Taejo Hubaekje başkentine girdi ve Geç Üç Krallık birleşti","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Concu (Jeonju)","etiket":["toprak-kazanc","konu-siyasi"],"d":"Taejo, Hubaekje kurucusu Gyeon Hwon'un çağrısıyla 936 sonbaharında Cheonan'da toplanıp Ilsan-gun'a ilerledi; Ilicheon karşısında 'bulut gibi kılıç' belirmesi ve Hubaekje generallerinin Gyeon Hwon'a teslim olmasıyla düşman bozuldu, 3.200 esir alındı, 5.700 kişi öldürüldü; Sin-geom ve kardeşleri teslim oldu. Taejo Hubaekje başkentine girip halka dokunulmamasını emretti ve üç Han'ı birleştirmiş oldu.","kaynak":"Goryeosa (高麗史, Koryŏ-sa; Wikisource neşri, zh.wikisource.org/wiki/高麗史), Sega 2 (卷二) Taejo 19. yıl: «秋九月…甲午，隔一利川而陣…神劒與其弟…及文武官僚來降…王入百濟都城»"},{"bolge":1,"t":"0936-09-26","kesinlik":"gun","b":"Ilicheon'da Goryeo, Hubaekje ordusunu yendi; Sin-geom teslim oldu, Taejo Hubaekje başkentine girdi ve Geç Üç Krallık birleşti","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Kongcu (Gongju)","etiket":["toprak-kazanc","konu-siyasi"],"d":"Taejo, Hubaekje kurucusu Gyeon Hwon'un çağrısıyla 936 sonbaharında Cheonan'da toplanıp Ilsan-gun'a ilerledi; Ilicheon karşısında 'bulut gibi kılıç' belirmesi ve Hubaekje generallerinin Gyeon Hwon'a teslim olmasıyla düşman bozuldu, 3.200 esir alındı, 5.700 kişi öldürüldü; Sin-geom ve kardeşleri teslim oldu. Taejo Hubaekje başkentine girip halka dokunulmamasını emretti ve üç Han'ı birleştirmiş oldu. (Hubaekje ülkesi.)","kaynak":"Goryeosa (高麗史, Koryŏ-sa; Wikisource neşri, zh.wikisource.org/wiki/高麗史), Sega 2 (卷二) Taejo 19. yıl: «秋九月…甲午，隔一利川而陣…神劒與其弟…及文武官僚來降…王入百濟都城»"},{"bolge":1,"t":"0936-09-26","kesinlik":"gun","b":"Ilicheon'da Goryeo, Hubaekje ordusunu yendi; Sin-geom teslim oldu, Taejo Hubaekje başkentine girdi ve Geç Üç Krallık birleşti","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Sabi (Buyeo)","etiket":["toprak-kazanc","konu-siyasi"],"d":"Taejo, Hubaekje kurucusu Gyeon Hwon'un çağrısıyla 936 sonbaharında Cheonan'da toplanıp Ilsan-gun'a ilerledi; Ilicheon karşısında 'bulut gibi kılıç' belirmesi ve Hubaekje generallerinin Gyeon Hwon'a teslim olmasıyla düşman bozuldu, 3.200 esir alındı, 5.700 kişi öldürüldü; Sin-geom ve kardeşleri teslim oldu. Taejo Hubaekje başkentine girip halka dokunulmamasını emretti ve üç Han'ı birleştirmiş oldu. (Hubaekje ülkesi.)","kaynak":"Goryeosa (高麗史, Koryŏ-sa; Wikisource neşri, zh.wikisource.org/wiki/高麗史), Sega 2 (卷二) Taejo 19. yıl: «秋九月…甲午，隔一利川而陣…神劒與其弟…及文武官僚來降…王入百濟都城»"},{"bolge":1,"t":"1009-01-01","kesinlik":"yil","b":"Lý Công Uẩn Lê hanedanının ardından tahta çıktı; Lý hanedanı kuruldu (1009-1225)","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Hanoi (Thăng Long)","etiket":["kurulus","konu-siyasi"],"d":"Le Hoan'ın ölümünden dört yıl içinde Keşişlerce yetiştirilip Hoa Lư sarayında kariyer yapan Lý Công Uẩn kral oldu ve sarayı Hoa Lư'dan Đại La'ya taşıdı. Taylor, Lý Công Uẩn'ın saltanatını 1009-1028 olarak verir; Song 1010'da onu vasal olarak tanıdı.","kaynak":"Taylor, K. W., A History of the Vietnamese, Cambridge University Press, 2013, bölüm 'Lý hanedanı' («Ly Cong Uan (1009-1028)»)"},{"bolge":1,"t":"1025-01-01","kesinlik":"yil","b":"Chola kralı I. Rajendra'nın deniz seferi: Sriwijaya (Palembang), Pannai ve Kadaram (Kedah) limanları yağmalandı, kral Sangramavijayottunggavarman esir alındı","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Palembang","etiket":["savas","konu-siyasi"],"d":"Tanjore'deki Rajendra yazıtına (1030-31) göre Chola filosu Kadaram kralını yakaladı, Sriwijaya (Palembang), Pannai ve başka merkezleri fethetti/yağmaladı. Coedès'e göre baskın Sumatra krallığını geçici olarak zayıflattı; bu zayıflama Doğu Cava'daki olayları da etkiledi.","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, bölüm VIII.1 («the great raid of 1025, details of which are given in an inscription of Rajendrachoja at Tanjore dated 1030-31»)"},{"bolge":1,"t":"1087-01-01","kesinlik":"yil","b":"Geç Üç Yıl Savaşı'nın sonunda Mutsu ve Dewa Kiyohira'nın elinde birleşti; Hiraizumi'de Ōshū Fujiwara hanedanı başladı","tur":"kurulus","onem":2,"dunya":1,"kapsam":"dis","yer_id":"Hiraizumi (Ōshū Fujiwara başkenti)","etiket":["kurulus","konu-siyasi"],"d":"Minamoto no Yoshiie'nin Kiyohara no Iehira'yı yenerek Geç Üç Yıl Savaşı'nı (1083-87) bitirmesinden sonra Mutsu ve Dewa Kiyohara no Kiyohira'nın yönetiminde birleşti; Kiyohira babasının Fujiwara soyadını alıp Hiraizumi'yi merkez yaptı (Ōshū Fujiwara). Bölge Yoritomo'nun 1189 fethine kadar merkezî denetimden bağımsız kaldı.","kaynak":"The Cambridge History of Japan, c. 2: Heian Japan (ed. D. H. Shively & W. H. McCullough), Cambridge UP, 1999, bölüm 10 ve kronoloji («Yoshiie finally defeats Kiyohara no Iehira, ending the Later Three Years' War. Mutsu and Dewa are united under Kiyohara no Kiyohira»)"},{"bolge":1,"t":"1113-01-01","kesinlik":"yil","b":"II. Suryavarman iki krallığı birleştirerek tahta çıktı; Brahman Divakara taç giydirdi (Angkor Vat'ın müstakbel banisi)","tur":"hukumdar","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Angkor (Siem Reap)","etiket":["hukumdar","konu-siyasi"],"d":"Coedès'e göre Suryavarman II bir günlük savaşın ardından Dharanindravarman I'i devirerek 'çifte krallığı' birleştirdi; taç giyme töreni 1113'te Divakara tarafından yapıldı. Hükümdar Çin, Dai Viet ve Champa'ya karşı büyük seferler yaptı, Angkor Vat onun döneminde inşa edildi.","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, bölüm X.5 ( «Divakara legitimized the coup de force ... by conducting his coronation in 1113»)"},{"bolge":1,"t":"1177-01-01","kesinlik":"yil","b":"Cham donanması Mekong ve Tonle Sap yoluyla Angkor'u basıp yağmaladı; Kmer kralı Tribhuvanaditya öldürüldü","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Angkor (Siem Reap)","etiket":["savas","konu-siyasi"],"d":"Kara seferi sonuçsuz kalan Cham kralı Jaya Indravarman 1177'de denizden saldırdı; Çinli bir kazazedenin kılavuzluğunda Mekong ağzına, oradan Büyük Göl'e (Tonle Sap) ulaşan filo Angkor'u baskınla alıp yağmaladı. Yirmi yıllık iç karışıklığın ardından gelen bu felaket Kmer krallığını sarstı.","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, bölüm X.5 («The expedition was sent in 1177 ... Angkor was surprised, the usurper Tribhuvanaditya killed, and the city pillaged»)"},{"bolge":1,"t":"1181-01-01","kesinlik":"yil","b":"VII. Jayavarman Cham istilasından dört yıl sonra taç giydi; Angkor'u surlarla ve hendekle çevirip yeniden kurdu (Angkor Thom)","tur":"hukumdar","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Angkor (Siem Reap)","etiket":["hukumdar","konu-siyasi"],"d":"1177 istilasını yenip ülkeyi toparlayan Jayavarman VII 1181'de taç giydi ve başkenti bugünkü Angkor Thom'un hendek ve surlarıyla yeniden inşa etti. Saltanatı (1181-yaklaşık 1220) Kmer devletinin en geniş sınırlara ulaştığı dönemdir; Champa'nın ilhakı bu saltanatta gerçekleşti.","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, s.169-170 («By 1181, four years after the invasion of 1177, Cambodia had become calm again and Jayavarman had himself crowned»)"},{"bolge":1,"t":"1185-01-01","kesinlik":"yil","b":"Genpei Savaşı'nın 1185'te Minamoto zaferiyle bitmesi: Kamakura'daki askerî hükûmet (bakufu) ülke çapında iktidara dönüştü","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Kamakura","etiket":["kurulus","konu-siyasi"],"d":"Minamoto no Yoritomo 1180'de Kamakura'yı üs edinmişti; Genpei Savaşı'nı (1180-85) kazanınca Kamakura, fiilî iktidarı elinde tutan askerî yönetimin merkezi oldu.","kaynak":"The Cambridge History of Japan, c. 3: Medieval Japan (ed. K. Yamamura), Cambridge UP, 1990, giriş kronolojisi («1180 Minamoto Yoritomo establishes base in Kamakura; 1180-5 Gempei War: Minamoto achieve victory over Taira») ve s."},{"bolge":1,"t":"1185-12-21","kesinlik":"gun","b":"Bunji Senedi: Hōjō Tokimasa'nın isteğiyle saray, Yoritomo'ya ülke çapında shugo ve jitō atama yetkisi verdi (Bunji 1/11/28)","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Hakata (Fukuoka)","etiket":["toprak-kazanc","konu-siyasi"],"d":"Yoshitsune'nin Yoritomo'ya karşı çıkmasının ardından, 1185 Aralık sonunda saray Hōjō Tokimasa'nın başvurusuyla Kamakura'ya her eyalette shugo (askerî-polis valisi) ve jitō (arazi/vergi yöneticisi) atama ve azletme yetkisi tanıdı. Bu, bakufunun taşrada kalıcı idari yetki kazandığı an sayılır (Bunji kuni-jitō). (Kyushu: shugo/jitō'nun uygulandığı bölge.)","kaynak":"The Cambridge History of Japan, c. 3: Medieval Japan (ed. K. Yamamura), Cambridge UP, 1990, bölüm 'Courtiers and Warriors' (Bunji kuni-jitō); gün: 文治元年11月28日 (ja.wikipedia 文治の勅許, Azuma Kagami ve Gyokuyō kayıtları)"},{"bolge":1,"t":"1185-12-21","kesinlik":"gun","b":"Bunji Senedi: Hōjō Tokimasa'nın isteğiyle saray, Yoritomo'ya ülke çapında shugo ve jitō atama yetkisi verdi (Bunji 1/11/28)","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Kyoto","etiket":["toprak-kazanc","konu-siyasi"],"d":"Yoshitsune'nin Yoritomo'ya karşı çıkmasının ardından, 1185 Aralık sonunda saray Hōjō Tokimasa'nın başvurusuyla Kamakura'ya her eyalette shugo (askerî-polis valisi) ve jitō (arazi/vergi yöneticisi) atama ve azletme yetkisi tanıdı. Bu, bakufunun taşrada kalıcı idari yetki kazandığı an sayılır (Bunji kuni-jitō). (Hōjō Tokimasa'nın saraydan bu yetkiyi koparttığı yer.)","kaynak":"The Cambridge History of Japan, c. 3: Medieval Japan (ed. K. Yamamura), Cambridge UP, 1990, bölüm 'Courtiers and Warriors' (Bunji kuni-jitō); gün: 文治元年11月28日 (ja.wikipedia 文治の勅許, Azuma Kagami ve Gyokuyō kayıtları)"},{"bolge":1,"t":"1185-12-21","kesinlik":"gun","b":"Bunji Senedi: Hōjō Tokimasa'nın isteğiyle saray, Yoritomo'ya ülke çapında shugo ve jitō atama yetkisi verdi (Bunji 1/11/28)","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Nara","etiket":["toprak-kazanc","konu-siyasi"],"d":"Yoshitsune'nin Yoritomo'ya karşı çıkmasının ardından, 1185 Aralık sonunda saray Hōjō Tokimasa'nın başvurusuyla Kamakura'ya her eyalette shugo (askerî-polis valisi) ve jitō (arazi/vergi yöneticisi) atama ve azletme yetkisi tanıdı. Bu, bakufunun taşrada kalıcı idari yetki kazandığı an sayılır (Bunji kuni-jitō). (Yamato: shugo/jitō'nun uygulandığı Kinai.)","kaynak":"The Cambridge History of Japan, c. 3: Medieval Japan (ed. K. Yamamura), Cambridge UP, 1990, bölüm 'Courtiers and Warriors' (Bunji kuni-jitō); gün: 文治元年11月28日 (ja.wikipedia 文治の勅許, Azuma Kagami ve Gyokuyō kayıtları)"},{"bolge":1,"t":"1185-12-21","kesinlik":"gun","b":"Bunji Senedi: Hōjō Tokimasa'nın isteğiyle saray, Yoritomo'ya ülke çapında shugo ve jitō atama yetkisi verdi (Bunji 1/11/28)","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Osaka","etiket":["toprak-kazanc","konu-siyasi"],"d":"Yoshitsune'nin Yoritomo'ya karşı çıkmasının ardından, 1185 Aralık sonunda saray Hōjō Tokimasa'nın başvurusuyla Kamakura'ya her eyalette shugo (askerî-polis valisi) ve jitō (arazi/vergi yöneticisi) atama ve azletme yetkisi tanıdı. Bu, bakufunun taşrada kalıcı idari yetki kazandığı an sayılır (Bunji kuni-jitō). (Settsu: shugo/jitō'nun uygulandığı Kinai.)","kaynak":"The Cambridge History of Japan, c. 3: Medieval Japan (ed. K. Yamamura), Cambridge UP, 1990, bölüm 'Courtiers and Warriors' (Bunji kuni-jitō); gün: 文治元年11月28日 (ja.wikipedia 文治の勅許, Azuma Kagami ve Gyokuyō kayıtları)"},{"bolge":1,"t":"1189-01-01","kesinlik":"yil","b":"Yoritomo Ōshū Fujiwara'yı yok edip Mutsu-Dewa'yı fethetti; Hiraizumi Kamakura egemenliğine girdi (1189)","tur":"toprak-kazanc","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Hiraizumi (Ōshū Fujiwara başkenti)","etiket":["toprak-kazanc","konu-siyasi"],"d":"Cambridge History'ye göre Mutsu-Dewa'daki Fujiwara kolu, Minamoto no Yoritomo'nun 1189 fethine kadar merkezî denetimden bağımsız kaldı; son lider Yasuhira (1155-89) o yıl öldü.","kaynak":"The Cambridge History of Japan, c. 2: Heian Japan (ed. D. H. Shively & W. H. McCullough), Cambridge UP, 1999, bölüm 10 ve Şekil 10.2 («remaining independent of central control until the time of Minamoto no Yoritomo's conquest in 1189»)"},{"bolge":1,"t":"1192-08-21","kesinlik":"gun","b":"Minamoto no Yoritomo sei-i taishōgun (şogun) unvanını aldı","tur":"hukumdar","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Kamakura","etiket":["hukumdar","konu-siyasi"],"d":"Saray, 1192'de Yoritomo'ya 'barbar-bastıran başkomutan' (sei-i taishōgun) unvanını vererek Kamakura'daki fiilî askerî iktidarı resmen tanıdı; Cambridge History bu yılı bakufunun resmî kuruluşu için olası dönüm noktalarından biri sayar.","kaynak":"The Cambridge History of Japan, c. 3: Medieval Japan (ed. K. Yamamura), Cambridge UP, 1990, sözlükçe/kronoloji («1192 Yoritomo given title of shogun»); gün: 建久3年7月12日 (ja.wikipedia 征夷大将軍)"},{"bolge":1,"t":"1220-01-01","kesinlik":"yil","b":"Sukhothai Tay beyliğinde Indraditya'nın tahta çıkışı (yaklaşık 1220): Kmer idaresinden kopuş ve Tay krallığının başlangıcı","tur":"kurulus","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Sukhothai","etiket":["kurulus","konu-siyasi"],"d":"Coedès, Sukhothai'nin bağımsızlığına ve Indraditya'nın krallığına dair kesin tarih bulunmadığını; Rama Khamhaeng'in (Indraditya'nın üçüncü oğlu, ikinci halefi) 13. yüzyılın son yirmi yılında hüküm sürmesinden geriye hesapla Indraditya'nın taç giymesinin yaklaşık 1220'ye düştüğünü belirtir.","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, bölüm XII.5 (Sukhothai'nin başlangıçları) («we can date the coronation of Indraditya around 1220»)"},{"bolge":1,"t":"1222-01-01","kesinlik":"yil","b":"Angrok (Ken Arok) Kadiri kralını devirdi; Tumapel merkezli Singhasari, Kadiri'nin yerini aldı (1222) ve eski Janggala topraklarını birleştirdi","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Malang","etiket":["toprak-kayip","konu-siyasi"],"d":"Coedès'e göre Kertajaya'nın saltanatının sonlarında (1222) Malang'ın kuzeydoğusundaki Tumapel'in yönetimini ele geçiren Angrok eski Janggala'yı kendi gücü altına aldı, ardından Kadiri kralına isyan etti; yeni hanedanın Tumapel'de kuruluşu iki kardeş krallığın yeniden birleşmesi sayılır. Janggala; Malang bölgesini ve Surabaya limanını içerirdi. (Tumapel'in bulunduğu Malang çevresi (eski Janggala).)","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, bölüm X.8 ve XI.8 («Near the end of his reign (in 1222), an adventurer named Angrok ... brought the former Janggala under his power»)"},{"bolge":1,"t":"1222-01-01","kesinlik":"yil","b":"Angrok (Ken Arok) Kadiri kralını devirdi; Tumapel merkezli Singhasari, Kadiri'nin yerini aldı (1222) ve eski Janggala topraklarını birleştirdi","tur":"toprak-kayip","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Surabaya","etiket":["toprak-kayip","konu-siyasi"],"d":"Coedès'e göre Kertajaya'nın saltanatının sonlarında (1222) Malang'ın kuzeydoğusundaki Tumapel'in yönetimini ele geçiren Angrok eski Janggala'yı kendi gücü altına aldı, ardından Kadiri kralına isyan etti; yeni hanedanın Tumapel'de kuruluşu iki kardeş krallığın yeniden birleşmesi sayılır. Janggala; Malang bölgesini ve Surabaya limanını içerirdi. (Brantas deltası (eski Janggala).)","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, bölüm X.8 ve XI.8 («Near the end of his reign (in 1222), an adventurer named Angrok ... brought the former Janggala under his power»)"},{"bolge":1,"t":"1232-07-05","kesinlik":"gun","b":"Choe U kralı zorlayarak başkenti Ganghwa Adası'na taşıdı (Moğol istilalarına karşı)","tur":"baskent","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Ganghwa","etiket":["baskent","konu-siyasi"],"d":"İlk Moğol istilasının (1231) ardından Moğol baskısı üzerine Choe U, Kral Gojong'u zorlayarak sarayı Ganghwa'ya taşıttı; ertesi gün Ganghwa'da saray inşasına başlandı. Taşınma Goryeo'nun Moğollara karşı otuz yıl süren direniş stratejisinin başlangıcıdır.","kaynak":"Goryeosa (高麗史, Koryŏ-sa; Wikisource neşri, zh.wikisource.org/wiki/高麗史), Sega 23 (卷二十三) Gojong 19. yıl: «六月…乙丑，崔瑀脅王，遷都江華。丙寅，瑀發二領軍，始營宮闕于江華»"},{"bolge":1,"t":"1257-01-01","kesinlik":"yil","b":"Moğol komutanı Uriyangqadai Yunnan'dan Kızıl Nehir boyunca Thăng Long'a ilerledi (1257): Trần'a karşı ilk Moğol işgali","tur":"savas","onem":2,"dunya":2,"kapsam":"dis","yer_id":"Hanoi (Thăng Long)","etiket":["savas","konu-siyasi"],"d":"Nanzhao'yu (Yunnan) ezen Uriyangqadai, 1257 yaz-sonbaharında yaklaşık 25.000 kişilik (5.000 Moğol, 20.000 Yunnanlı) kuvvetle Kızıl Nehir boyunca Thăng Long'a ilerledi; amacı Güney Song'a güneyden saldırmaktı. Taylor olayı Trần devletinin benzeri görülmemiş bir krizi olarak anlatır.","kaynak":"Taylor, K. W., A History of the Vietnamese, Cambridge University Press, 2013, Trần-Moğol savaşları bölümü («In summer and autumn of 1257, Uriyangqadai advanced downriver through the mountains toward Thang Long»)"},{"bolge":1,"t":"1269-10-29","kesinlik":"gun","b":"Choe Tan'ın kuzeybatı isyanı: Seogyeong (Pyongyang) naibi ve beş ilin valisi öldürüldü, bölge Moğollara teslim edilmeye yöneldi","tur":"isyan","onem":2,"dunya":1,"kapsam":"dis","yer_id":"Pyongyang","etiket":["isyan","konu-siyasi"],"d":"Lim Yeon'un kralı tahttan indirmesini bahane eden kuzeybatı bölgesi komutanlığı kâtibi Choe Tan ve arkadaşları ayaklanıp Seogyeong naibini ve Yong, Yeong, Cheol, Seon, Ja illerinin valilerini öldürdü; Choe Tan Moğol elçisine bunun 'Goryeo'nun adalara çekilme hazırlığına' karşı olduğunu söyledi. Bölge sonradan Moğollara bağlanıp Dongnyeong-bu (1270) adıyla yönetildi.","kaynak":"Goryeosa (高麗史, Koryŏ-sa; Wikisource neşri, zh.wikisource.org/wiki/高麗史), Sega 26 (卷二十六) Wonjong 10. yıl: «冬十月…乙亥，西北面兵馬使營記官崔坦、韓愼…嘯聚龍岡、咸從、三和人，殺…»; Dongnyeong-bu'nun kuruluşu aynı sega, Wonjong 11. yıl"},{"bolge":1,"t":"1271-06-23","kesinlik":"gun","b":"Kim Bang-gyeong ve Moğol komutanlar Jindo'daki Sambyeolcho üssünü ezdi; sahte kral Seung-hwa-hu On öldürüldü","tur":"toprak-kazanc","onem":2,"dunya":1,"kapsam":"dis","yer_id":"Jindo","etiket":["toprak-kazanc","konu-siyasi"],"d":"Sambyeolcho (seçkin muhafız birliği) isyanının Jindo'daki merkezi, 1271'de Kim Bang-gyeong, Hindu (Xindu) ve Hong Da-gu'nun komutasındaki üç kolun saldırısıyla ele geçirildi; sahte kral Seung-hwa-hu On öldürüldü, artakalanlar Jeju'ya (Tamna) kaçtı.","kaynak":"Goryeosa (高麗史, Koryŏ-sa; Wikisource neşri, zh.wikisource.org/wiki/高麗史), Sega 27 (卷二十七) Wonjong 12. yıl: «夏五月…丁丑，金方慶、忻都、茶丘、熙、雍等率三軍，討珍島，大破之，斬僞王承化侯溫。賊將金通精，率餘衆，竄入耽羅»"},{"bolge":1,"t":"1273-05-16","kesinlik":"gun","b":"Kim Bang-gyeong ve Hindu Jeju'da (Tamna) Sambyeolcho'yu yok etti; isyan sona erdi","tur":"savas","onem":2,"dunya":1,"kapsam":"dis","yer_id":"Ceccu (Jeju)","etiket":["savas","konu-siyasi"],"d":"1273 baharında 160 gemi ve on binden fazla askerle Jeju'ya çıkan Kim Bang-gyeong ile Hindu ve Hong Da-gu, Kim Won-yun dahil altı lideri öldürdü, 1.300 teslim olan asiyi gemilere ayırdı; Jeju'nun yerli halkı yerinde bırakıldı. Sambyeolcho isyanı böylece sona erdi.","kaynak":"Goryeosa (高麗史, Koryŏ-sa; Wikisource neşri, zh.wikisource.org/wiki/高麗史), Sega 28 (卷二十八) Wonjong 14. yıl: «夏四月…庚戌，金方慶與忻都、茶丘等，以全羅道一百六十艘、水陸兵一萬餘人至耽羅，與賊戰…於是賊悉平»"},{"bolge":1,"t":"1274-01-01","kesinlik":"yil","b":"Birinci Moğol (Yuan) istilası Kyushu kıyısında (Bun'ei seferi) 'kamikaze' fırtınasıyla püskürtüldü","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Hakata (Fukuoka)","etiket":["savas","konu-siyasi"],"d":"Moğol (Yuan) istila donanması 1274'te kıyıda fırtınada büyük kayıp verip çekildi.","kaynak":"The Cambridge History of Japan, c. 3: Medieval Japan (ed. K. Yamamura), Cambridge UP, 1990, sözlükçe «Kamikaze» («the storms that twice destroyed much of the invading Mongol forces in 1274 and 1281 off the coast of Kyushu»)"},{"bolge":1,"t":"1281-01-01","kesinlik":"yil","b":"İkinci Moğol (Yuan) istilası (Kōan seferi) Kyushu açıklarında fırtınayla bozguna uğradı","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Hakata (Fukuoka)","etiket":["savas","konu-siyasi"],"d":"1281'deki ikinci büyük istila donanması da Kyushu kıyısında fırtınada büyük ölçüde yok oldu; iki başarısız istila Kamakura bakufunun mali çöküşünü hızlandırdı.","kaynak":"The Cambridge History of Japan, c. 3: Medieval Japan (ed. K. Yamamura), Cambridge UP, 1990, sözlükçe «Kamikaze» («the storms that twice destroyed much of the invading Mongol forces in 1274 and 1281 off the coast of Kyushu»)"},{"bolge":1,"t":"1287-01-01","kesinlik":"yil","b":"Moğollar Pagan'ı ele geçirdi; Birman krallığı geçici olarak dağıldı, ülke Tay beylerinin yönettiği prensliklere bölündü","tur":"savas","onem":3,"dunya":2,"kapsam":"dis","yer_id":"Pagan","etiket":["savas","konu-siyasi"],"d":"Coedès, 1287'de Pagan'ın Moğollarca alınmasının Birman krallığının geçici olarak ortadan kalkmasına ve ülkenin Tay şeflerince yönetilen prensliklere bölünmesine yol açtığını yazar; aynı yıl Mangrai, Ngam Müang ve Rama Khamhaeng Tay ittifakını kurdu. Narathihapate 'Tarukphyi' ('Moğollardan kaçan') diye anıldı.","kaynak":"Coedès, G., The Indianized States of Southeast Asia (çev. S. B. Cowing; ed. W. F. Vella), Honolulu: East-West Center Press, 1968, bölüm XII.4 ve s.189 vd. («the seizure of Pagan by the Mongols in 1287 resulted in the temporary disappearance of the Burmese kingdom»)"}];

